def _key(operation: str, reference: str) -> str:
    return f"pl-{operation}-{hashlib.sha1(reference.encode('utf-8')).hexdigest()[:16]}"


def _code(r: Response) -> str:
    try:
        return str(json.loads(r.body)["error"]["code"])
    except (ValueError, KeyError, TypeError):
        return ""


def _error(r: Response) -> ApiError:
    return ApiError(r.status, _code(r))


def _retryable(r: Response) -> bool:
    if r.status in RETRY_STATUSES:
        return True
    return r.status == 409 and _code(r) == "idempotency_in_progress"


def _wait(transport: Transport, failed: int, r: Response | None) -> None:
    """Waits before the next attempt; `failed` is the number of attempts made so far."""
    seconds: float = BACKOFF[failed - 1]
    if r is not None:
        for name, value in r.headers.items():
            if name.lower() == "retry-after":
                try:
                    seconds = int(str(value).strip())
                except ValueError:
                    pass
                break
    transport.sleep(seconds)


def _call(transport: Transport, method: str, path: str, body: dict[str, Any] | None = None, key: str | None = None) -> Any:
    headers = {"Idempotency-Key": key} if key is not None else {}
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            r = transport.send(method, path, dict(headers), body)
        except ConnectionError:
            if attempt == MAX_ATTEMPTS:
